/* SheetJS xlsx 0.18.5 loader. Kept at this local filename so index.html can load it with ./xlsx.full.min.js. */
document.write('<script src="https://cdnjs.cloudflare.com/ajax/libs/xlsx/0.18.5/xlsx.full.min.js"><\/script>');

/* Cross-verification export extension
 * contractsubject: 과제명=O(14), 연구시작일자=R(17), 연구종료일자=S(18)
 * 화면 결과표는 유지하고 Excel/CSV 다운로드 레이아웃만 확장합니다.
 */
window.addEventListener('DOMContentLoaded', function () {
  const originalBuildAgg = window.buildAgg;
  const originalStatusRow = window.statusRow;

  function clean(v) {
    return v === null || v === undefined ? '' : String(v).trim();
  }

  function formatDate(v) {
    if (v === null || v === undefined || v === '') return '';
    if (typeof v === 'number' && window.XLSX && XLSX.SSF && XLSX.SSF.parse_date_code) {
      const d = XLSX.SSF.parse_date_code(v);
      if (d && d.y) {
        return String(d.y).padStart(4,'0') + '-' + String(d.m).padStart(2,'0') + '-' + String(d.d).padStart(2,'0');
      }
    }
    const s = clean(v);
    const m = s.match(/^(\d{4})[-/.](\d{1,2})[-/.](\d{1,2})/);
    if (m) return m[1] + '-' + m[2].padStart(2,'0') + '-' + m[3].padStart(2,'0');
    return s;
  }

  if (typeof originalBuildAgg === 'function') {
    window.buildAgg = function (rows, type, monthCols) {
      const map = originalBuildAgg(rows, type, monthCols);
      if (type === 'contract' && map && rows) {
        const meta = new Map();
        for (const row of rows) {
          const emp = clean(row && row[6]);
          const project = clean(row && row[13]);
          const year = clean(row && row[23]);
          if (!emp || !project || !year) continue;
          const k = [emp, project, year].join('\u001f');
          if (!meta.has(k)) {
            meta.set(k, {
              projectName: clean(row[14]),
              researchStart: formatDate(row[17]),
              researchEnd: formatDate(row[18])
            });
          } else {
            const x = meta.get(k);
            if (!x.projectName) x.projectName = clean(row[14]);
            if (!x.researchStart) x.researchStart = formatDate(row[17]);
            if (!x.researchEnd) x.researchEnd = formatDate(row[18]);
          }
        }
        for (const [k, obj] of map.entries()) {
          const x = meta.get(k);
          if (x) Object.assign(obj, x);
        }
      }
      return map;
    };
  }

  if (typeof originalStatusRow === 'function') {
    window.statusRow = function (status, obj, month, ca, ja) {
      const r = originalStatusRow(status, obj, month, ca, ja);
      r['과제명'] = obj && obj.projectName ? obj.projectName : '';
      r['연구시작일자'] = obj && obj.researchStart ? obj.researchStart : '';
      r['연구종료일자'] = obj && obj.researchEnd ? obj.researchEnd : '';
      return r;
    };
  }

  window.exportRows = function () {
    return (window.results || []).map(function (r) {
      return {
        '상태': r['상태'],
        '직번': r['직번'],
        '성명': r['성명'],
        '과제번호': r['과제번호'],
        '과제명': r['과제명'] || '',
        '연구시작일자': r['연구시작일자'] || '',
        '연구종료일자': r['연구종료일자'] || '',
        '년도': r['년도'],
        '불일치월': r['불일치월'],
        '계약관리 지급액': r['계약관리 지급액'],
        '참여인력 예정액': r['참여인력 예정액'],
        '차액': r['차액']
      };
    });
  };
});
